import{_ as r,a as c,b as s}from"./chunks/PageInfo.vue_vue_type_script_setup_true_lang.BCVHfIj7.js";import{_ as i,c as n,I as a,a7 as l,o as h}from"./chunks/framework.DGCt2JJv.js";import"./chunks/dayjs.min.DZyl58SH.js";const C=JSON.parse('{"title":"React组件性能优化中如何避免频繁更新？","description":"","frontmatter":{},"headers":[],"relativePath":"react/性能监控/React组件性能优化中如何避免频繁更新.md","filePath":"react/性能监控/React组件性能优化中如何避免频繁更新.md","lastUpdated":1720367503000}'),p={name:"react/性能监控/React组件性能优化中如何避免频繁更新.md"},d=l('<h1 id="react组件性能优化中如何避免频繁更新" tabindex="-1">React组件性能优化中如何避免频繁更新？ <a class="header-anchor" href="#react组件性能优化中如何避免频繁更新" aria-label="Permalink to &quot;React组件性能优化中如何避免频繁更新？&quot;">​</a></h1><h2 id="使用react-memo" tabindex="-1">使用React.memo： <a class="header-anchor" href="#使用react-memo" aria-label="Permalink to &quot;使用React.memo：&quot;">​</a></h2><p>对于函数组件，可以使用<code>React.memo</code>来避免不必要的重新渲染。它通过浅比较传递给组件的props来确定是否需要更新</p><h2 id="使用usememo" tabindex="-1">使用useMemo： <a class="header-anchor" href="#使用usememo" aria-label="Permalink to &quot;使用useMemo：&quot;">​</a></h2><p><code>useMemo</code>可以用来缓存那些耗时的计算结果，只有在依赖项发生变化时才重新计算。这有助于减少因依赖项未改变而引起的不必要的渲染</p><h2 id="使用usecallback" tabindex="-1">使用useCallback： <a class="header-anchor" href="#使用usecallback" aria-label="Permalink to &quot;使用useCallback：&quot;">​</a></h2><p>通过<code>useCallback</code>返回一个稳定的回调函数，这样依赖该回调的组件就不会因为每次渲染时都获得新的函数引用而重新渲染</p><h2 id="批量状态更新" tabindex="-1">批量状态更新： <a class="header-anchor" href="#批量状态更新" aria-label="Permalink to &quot;批量状态更新：&quot;">​</a></h2><p>在事件处理函数和生命周期方法中，React会自动对连续的状态变更进行批量处理，从而减少实际的渲染次数。</p><p>但在非这些情况下，应手动合并状态更新，以避免触发多次渲染</p><h2 id="避免不必要的props变化" tabindex="-1">避免不必要的props变化： <a class="header-anchor" href="#避免不必要的props变化" aria-label="Permalink to &quot;避免不必要的props变化：&quot;">​</a></h2><p>确保传递给子组件的props确实是子组件需要的，避免传递不必要的props，这样可以减少子组件因为父组件状态变化而被不必要地重新渲染</p><h2 id="稳定键的使用" tabindex="-1">稳定键的使用： <a class="header-anchor" href="#稳定键的使用" aria-label="Permalink to &quot;稳定键的使用：&quot;">​</a></h2><p>在渲染列表时，为每个列表项提供一个稳定的键（key），可以帮助React更高效地进行DOM差异比较，减少不必要的DOM操作</p><h2 id="避免不必要的状态更新" tabindex="-1">避免不必要的状态更新： <a class="header-anchor" href="#避免不必要的状态更新" aria-label="Permalink to &quot;避免不必要的状态更新：&quot;">​</a></h2><p>在处理应用状态时，应避免不必要的状态更新。例如，可以通过条件语句检查新状态与当前状态是否相同，从而避免无谓的状态更新</p><blockquote><p>减轻 state, 降低页面更新的频率 （只要state中数据发生改变，页面就会重载）</p></blockquote><p>不用做渲染的数据不要放在state中,比如定时器 id</p><h2 id="避免复杂的计算" tabindex="-1">避免复杂的计算： <a class="header-anchor" href="#避免复杂的计算" aria-label="Permalink to &quot;避免复杂的计算：&quot;">​</a></h2><p>在渲染过程中避免进行复杂的计算，特别是那些不会影响渲染结果的计算。</p><p>可以将计算结果缓存起来，或者将计算过程移到组件的生命周期方法中，而不是在渲染过程中进行</p><h2 id="使用不可变数据结构" tabindex="-1">使用不可变数据结构： <a class="header-anchor" href="#使用不可变数据结构" aria-label="Permalink to &quot;使用不可变数据结构：&quot;">​</a></h2><p>使用不可变数据结构可以帮助React更有效地判断状态是否发生了变化，从而避免不必要的更新。</p><p>不可变数据结构可以带来零副作用、便于测试和使用、利于解耦以及更容易追踪变化等好处</p><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2>',25);function _(m,u,b,f,q,k){const e=r,t=c,o=s;return h(),n("div",null,[d,a(e,{readTime:"1",words:"648"}),a(t),a(o)])}const T=i(p,[["render",_]]);export{C as __pageData,T as default};
